import{_ as a,C as s,o as n,c as o,j as r,a as l,E as i,a2 as u}from"./chunks/framework.BxGh02fV.js";const v=JSON.parse('{"title":"Fenêtre, barres et systray","description":"","frontmatter":{"title":"Fenêtre, barres et systray"},"headers":[],"relativePath":"guide/window.md","filePath":"guide/window.md"}'),d={name:"guide/window.md"};function c(g,e,p,f,m,h){const t=s("Capture");return n(),o("div",null,[e[0]||(e[0]=r("h1",{id:"fenetre-barres-et-systray",tabindex:"-1"},[l("Fenêtre, barres et systray "),r("a",{class:"header-anchor",href:"#fenetre-barres-et-systray","aria-label":'Permalink to "Fenêtre, barres et systray"'},"​")],-1)),e[1]||(e[1]=r("p",null,"Quel que soit l'écran, la fenêtre d'Effortless garde la même charpente : une barre du haut pour les onglets et les réglages de lecture, une barre latérale pour naviguer dans un workspace, et une icône dans le systray qui garde l'application active quand la fenêtre est fermée.",-1)),i(t,{name:"fenetre",alt:"La fenêtre d'un workspace : barre du haut avec onglets, thème, confort et profil ; barre latérale à gauche"}),e[2]||(e[2]=u('<h2 id="la-barre-du-haut" tabindex="-1">La barre du haut <a class="header-anchor" href="#la-barre-du-haut" aria-label="Permalink to &quot;La barre du haut&quot;">​</a></h2><p>De gauche à droite :</p><ul><li><strong>L&#39;icône de grille</strong> (« Espaces de travail ») : ramène au sélecteur (<a href="/Effortless/guide/start.html">Ouvrir un workspace</a>).</li><li><strong>Les onglets</strong> : un par workspace ouvert, avec son nom. Cliquez sur un onglet pour y revenir ; sa croix <strong>✕</strong> le ferme. Fermer le dernier onglet ramène au sélecteur.</li><li><strong>+</strong> (« Nouvel onglet ») : ramène lui aussi au sélecteur. L&#39;onglet est créé quand vous y ouvrez un projet ; si le projet est déjà ouvert, son onglet est réactivé.</li><li><strong>Le bouton soleil/lune</strong> : bascule entre thème clair et thème sombre. Ce choix s&#39;enregistre dans votre profil ; si vous étiez en thème <strong>Système</strong>, il le remplace par un thème explicite.</li><li><strong>Aa</strong> (« Confort de lecture ») : un menu à trois choix, <strong>Compact</strong>, <strong>Standard</strong> et <strong>Confortable</strong>, qui règle ensemble la taille des éléments et la densité de l&#39;interface.</li><li><strong>Votre nom et votre avatar</strong> : ouvrent les <a href="/Effortless/guide/preferences.html">préférences</a>. Pour en sortir, cliquez sur un onglet ou sur l&#39;icône de grille.</li><li><strong>Le témoin de fraîcheur</strong> : une petite diode. Elle dit quand l&#39;application a reçu pour la dernière fois une mise à jour du projet (« Reçu il y a 2 minutes », par exemple). Un clic ouvre <strong>Fraîcheur des données</strong>, avec un bouton <strong>Relire</strong> qui relit l&#39;état du projet. Si la surveillance du dossier s&#39;interrompt, le témoin l&#39;écrit en toutes lettres.</li><li><strong>Sous Windows</strong>, la barre porte aussi les boutons de fenêtre <strong>Réduire</strong>, <strong>Agrandir</strong> et <strong>Fermer</strong>.</li></ul><h2 id="la-barre-laterale" tabindex="-1">La barre latérale <a class="header-anchor" href="#la-barre-laterale" aria-label="Permalink to &quot;La barre latérale&quot;">​</a></h2><p>Elle n&#39;apparaît que dans un workspace.</p><ul><li><strong>En haut</strong> : la mascotte et le nom Effortless, avec une flèche qui replie la barre en un rail d&#39;icônes. Repliée, cliquez sur la mascotte pour la déplier.</li><li><strong>Les écrans</strong>, rangés par groupe : <strong>Pilotage</strong> (<a href="/Effortless/guide/dashboard.html">Tableau de bord</a>), <strong>Backlog &amp; travail</strong> (<a href="/Effortless/guide/backlog.html">Backlog</a>, <a href="/Effortless/guide/tasks.html">Tâches</a>), <strong>Cadrage &amp; connaissance</strong> (<a href="/Effortless/guide/knowledge.html">Connaissance</a>), <strong>Qualité &amp; versioning</strong> (<a href="/Effortless/guide/drift.html">Dérive</a>, <a href="/Effortless/guide/git.html">Git</a>, <a href="/Effortless/guide/release.html">Livraison</a>, <a href="/Effortless/guide/modules.html">Modules</a>).</li><li><strong>En bas</strong> : le nom du workspace et la version <strong>du projet</strong> (par exemple <code>v0.1.0</code>, lue dans <code>effortless.json</code> — ce n&#39;est pas la version de l&#39;application), puis <a href="/Effortless/guide/settings.html">Réglages</a> et <a href="/Effortless/guide/help.html">Aide</a>.</li></ul><p>Glissez le bord droit de la barre pour changer sa largeur ; au clavier, placez le focus sur ce bord et utilisez les flèches gauche et droite.</p><p>Au-dessus de chaque écran, un en-tête rappelle le nom de l&#39;écran à gauche et le nom du projet à droite.</p><h2 id="les-notifications" tabindex="-1">Les notifications <a class="header-anchor" href="#les-notifications" aria-label="Permalink to &quot;Les notifications&quot;">​</a></h2><p>De petites notifications apparaissent en bas à droite de la fenêtre, puis disparaissent seules ; leur croix les ferme plus tôt. Elles signalent par exemple qu&#39;une nouvelle version est disponible, que les normes de développement ont été mises à jour au démarrage ou à l&#39;ouverture d&#39;un projet, ou qu&#39;un auto-commit des métadonnées a été fait (voir <a href="/Effortless/guide/git.html">Git</a>).</p><h2 id="raccourcis-clavier" tabindex="-1">Raccourcis clavier <a class="header-anchor" href="#raccourcis-clavier" aria-label="Permalink to &quot;Raccourcis clavier&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Action</th><th>macOS</th><th>Windows et Linux</th></tr></thead><tbody><tr><td>Ouvrir les préférences</td><td>⌘ ,</td><td>Ctrl+,</td></tr><tr><td>Fermer l&#39;onglet workspace courant</td><td>⌘ W</td><td>Ctrl+W</td></tr><tr><td>Nouvel onglet (le sélecteur)</td><td>⌘ N</td><td>Ctrl+N</td></tr></tbody></table><p>Sous macOS, <strong>Nouvel onglet</strong> et <strong>Fermer l&#39;onglet</strong> figurent aussi dans le menu <strong>Fichier</strong> de l&#39;application.</p><h2 id="fermer-la-fenetre-et-le-systray" tabindex="-1">Fermer la fenêtre et le systray <a class="header-anchor" href="#fermer-la-fenetre-et-le-systray" aria-label="Permalink to &quot;Fermer la fenêtre et le systray&quot;">​</a></h2><p>Fermer la fenêtre ne quitte pas Effortless : la fenêtre se masque, et l&#39;application continue de tourner, avec son icône dans la barre de menus (macOS) ou la zone de notification (Windows).</p><p>Cliquez sur l&#39;icône pour ouvrir son menu :</p><ul><li><strong>Ouvrir Effortless</strong> : réaffiche la fenêtre.</li><li><strong>Sessions MCP</strong> : la liste des sessions MCP en cours, une ligne par agent connecté (nom du projet et numéro de processus), ou « Aucune session ». La liste se met à jour toute seule, toutes les trois secondes.</li><li><strong>Quitter</strong> : arrête réellement l&#39;application.</li></ul><p>Le menu du systray, comme le menu de l&#39;application sous macOS, suit la langue choisie dans les préférences.</p><h2 id="avec-un-agent-ia" tabindex="-1">Avec un agent IA <a class="header-anchor" href="#avec-un-agent-ia" aria-label="Permalink to &quot;Avec un agent IA&quot;">​</a></h2><p>Un agent ne passe pas par la fenêtre. Chaque agent connecté apparaît en revanche dans <strong>Sessions MCP</strong>, tant que sa session est ouverte.</p>',20))])}const q=a(d,[["render",c]]);export{v as __pageData,q as default};
